# -*- coding: utf-8 -*-
"""Build data-src/food_vocab.json, the everyday Hebrew food vocabulary, from the entries below.
Run from the project root:  python -I data-src/make_vocab.py   then   python -I data-src/check_vocab.py --table
Every id / raw is a smlmitzrach of the Ministry of Health table (data-src/moh/foods.json).
When raw is given and y is left None, y is computed as kcal_raw / kcal_cooked (energy kept the same when cooked without fat).
"""
import io, json, sys
sys.stdout.reconfigure(encoding='utf-8')

FOODS = {int(f['smlmitzrach']): f for f in json.loads(io.open('data-src/moh/foods.json', encoding='utf-8').read())['rows']}
OUT = []

def E(k, a, en, id, u, ug, d, c, kv, al='', units=None, raw=None, y=None, pk=None, pu=None, buy=None):
    """kv = kosher letter + vegan digit, e.g. 'd1', 'p2', 'm0', 'f0', 'x0'."""
    e = {'k': k, 'a': a, 'en': en, 'id': id}
    if raw is not None:
        if y is None:
            y = round(float(FOODS[raw]['food_energy']) / float(FOODS[id]['food_energy']), 2)
        e['raw'], e['y'] = raw, y
    e.update({'u': u, 'ug': ug})
    if units: e['units'] = units
    e.update({'d': d, 'c': c, 'ko': kv[0], 'vg': int(kv[1]), 'al': al.split() if al else []})
    if pk is not None:
        e.update({'pk': pk, 'pu': pu, 'buy': buy})
    OUT.append(e)

